  (* [comment removed for export] *)
  Lemma aim_cell_sound : forall E M k c v,
    know_ok SEGS E M k -> aim_cell SEGS k c v = true ->
    exists bs, rdn SEGS M (Z_to_bv 64 c) 8 = Some bs /\ bytes_le_to_Z bs = v.
Proof.
