  exact (proj1 (maps_match_exact 0%nat (fun _ => None) (fun _ _ _ => None) (fun _ _ _ => None) (fun _ _ _ => None) E (a_maps cs) _ Hnf)
               (co_maps _ _ _ _ _ _ _ _ _ _ _ HC)).
