Lemma hl_in_amapb : forall m ms, existsb (amap_eqb m) ms = true -> In m ms.
Proof. intros m ms H. apply existsb_exists in H as (m' & Hin & Heq). apply amap_eqb_eq in Heq. subst m'. exact Hin. Qed.

